import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,d as n}from"./app-c4483e21.js";const t={},l=n(`<h1 id="basic" tabindex="-1"><a class="header-anchor" href="#basic" aria-hidden="true">#</a> Basic</h1><p>First of all, when the program starts, it will run from the <strong>startup script</strong> <code>start.txt</code>. Please do not rename or delete it.</p><p>The following tutorials will teach you how to use WebGAL script.</p><h2 id="comments" tabindex="-1"><a class="header-anchor" href="#comments" aria-hidden="true">#</a> Comments</h2><p>WebGAL script will only parse the content before the semicolon in each line, so the content after the semicolon will be regarded as a comment.</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">Hello!</span><span style="color:#6272A4;">; The content after semicolon will be regarded as a comment</span></span>
<span class="line"><span style="color:#6272A4;">; You can directly input a semicolon, then write a single-line comment</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="multi-line-statements" tabindex="-1"><a class="header-anchor" href="#multi-line-statements" aria-hidden="true">#</a> Multi-line Statements</h2><p>When a statement has too many arguments, you can write it across multiple lines for readability.</p><p><strong>A continuation line must start with whitespace, and its first non-whitespace character must be <code>-</code> or <code>|</code>.</strong> Such a line is appended to the end of the previous statement, and the whole thing is still one statement.</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">stand.webp</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">left</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">id</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">fig1</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The above is equivalent to:</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">stand.webp </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">left</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">id</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">fig1</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>The text segments of <code>intro</code> can be continued with <code>|</code> in the same way:</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">First segment</span></span>
<span class="line"><span style="color:#F1FA8C;">  |Second segment</span></span>
<span class="line"><span style="color:#F1FA8C;">  |Third segment</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">hold</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The graphical editor automatically emits this format when a statement gets too long; short statements stay on a single line.</p><h3 id="rules-to-keep-in-mind" tabindex="-1"><a class="header-anchor" href="#rules-to-keep-in-mind" aria-hidden="true">#</a> Rules to Keep in Mind</h3><ul><li><strong>The semicolon and the inline comment may only appear on the last line.</strong> Everything after a semicolon is treated as a comment, so putting it on the first line would swallow the continuation lines.</li><li><strong>An empty line terminates a multi-line statement.</strong> Do not leave blank lines in the middle of one statement.</li><li><strong>Statements containing <code>-concat</code> are never continued automatically</strong>, because <code>-concat</code> itself means &quot;join this dialogue onto the previous one&quot; and the two semantics would conflict.</li><li><strong>A trailing backslash <code>\\</code> forces a continuation</strong>, which lets you bypass the restrictions above:</li></ul><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">First segment\\</span></span>
<span class="line"><span style="color:#F1FA8C;">|Second segment\\</span></span>
<span class="line"><span style="color:#F1FA8C;">|Third segment</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Compatibility note:</strong> a dialogue line starting with &quot;space + <code>-</code>&quot; will be mistaken for a continuation line. If you really want a dialogue to start with a dash, remove the leading space or put another character in front of it.</li></ul><h2 id="escaping-special-characters" tabindex="-1"><a class="header-anchor" href="#escaping-special-characters" aria-hidden="true">#</a> Escaping Special Characters</h2><p>WebGAL scripts use the English colon <code>:</code> to separate commands and content, the English semicolon <code>;</code> to end statements and start inline comments, and some commands also use symbols such as <code>|</code>, <code>,</code>, and <code>.</code> as part of their content syntax. If you want these symbols to be displayed as plain text, add a backslash <code>\\</code> before the symbol.</p><p>Common symbols that need escaping:</p><table><thead><tr><th style="text-align:left;">Original Symbol</th><th style="text-align:left;">Writing</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:</code></td><td style="text-align:left;"><code>\\:</code></td></tr><tr><td style="text-align:left;"><code>,</code></td><td style="text-align:left;"><code>\\,</code></td></tr><tr><td style="text-align:left;"><code>.</code></td><td style="text-align:left;"><code>\\.</code></td></tr><tr><td style="text-align:left;"><code>;</code></td><td style="text-align:left;"><code>\\;</code></td></tr><tr><td style="text-align:left;">\`</td><td style="text-align:left;">\`</td></tr></tbody></table><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">I will display these symbols\\: \\:\\,\\.\\</span><span style="color:#6272A4;">; just look -hold;</span></span>
<span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">I will display these symbols\\: \\:\\,\\.\\</span><span style="color:#6272A4;">; just look;</span></span>
<span class="line"><span style="color:#8BE9FD;">choose</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">I will display these symbols\\: \\:\\,\\.\\</span><span style="color:#6272A4;">; just look:nextLabel;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>When writing CSS in text extension syntax, semicolons also need to be written as <code>\\;</code>; otherwise, they will be treated as the start of a WebGAL statement comment.</p><h2 id="none-keyword" tabindex="-1"><a class="header-anchor" href="#none-keyword" aria-hidden="true">#</a> <code>none</code> Keyword</h2><p>When setting <strong>resources</strong> such as立ち絵, BGM, backgrounds, you can turn off this object by setting it to <code>none</code>.</p><h2 id="next-parameter" tabindex="-1"><a class="header-anchor" href="#next-parameter" aria-hidden="true">#</a> <code>-next</code> Parameter</h2><p>You can add the parameter <code>-next</code> after any statement. This will cause the next statement to be executed immediately after this statement is executed. This is very useful when you need to perform multiple operations at the same time.</p><p>Example:</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeBg</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">testBG03.jpg </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">; // Will execute the next statement immediately</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="notend-and-concat-parameters" tabindex="-1"><a class="header-anchor" href="#notend-and-concat-parameters" aria-hidden="true">#</a> <code>-notend</code> and <code>-concat</code> Parameters</h2><p>Sometimes, you may want to add 演出効果, such as switching expressions, when a certain stage of a dialogue is executed.<br> At this time, you can use the <code>-notend</code> <code>-concat</code> parameters to insert any statement in the dialogue.</p><p><code>-concat</code> means that this dialogue is connected after the previous dialogue</p><p><code>-notend</code> means that this dialogue is not over, and there may be 演出 or dialogue connected later.</p><p>An example is given below: This is a demonstration of switching 立ち絵 in the middle of a dialogue.</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">Test statement insert 演出！Switch 立ち絵 immediately......</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">notend</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">k1.png </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">Switch 立ち絵！Switch expression immediately......</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">notend</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">k2.png </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">Switch expression！</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>You can also use only the <code>-concat</code> parameter to connect the next sentence after the previous dialogue, because the <code>-notend</code> parameter will move to the next sentence after the dialogue fades in.</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F1FA8C;">This is the first sentence...</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">This sentence will only appear after the user clicks the mouse</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div>`,39),o=[l];function i(c,r){return s(),a("div",null,o)}const F=e(t,[["render",i],["__file","base.html.vue"]]);export{F as default};
